) AS (
  VALUES 
    (211::BIGINT, 'Póngale atención a lo que explica, tome apuntes y haga las cosas con tiempo. La cátedra NUNCA cambia las prácticas, si se las consigue, fácil las copia. Los quizzes son gaaps, y el examen fue de las prácticas que no entregaron reporte (circuitos, campo magnético).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '5bb8f1d0242962e824a8334710642c8a7e530e05fd898a62da9378dfd1dfc563'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Es un poco serio pero despues es vacilón y gracioso. Califica bien y no es duro, solo es ser responsable, la verdad lor ecomiendo totalmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9a62c128c402e837d56a95cdd0bd7179a261d2e7dae36617849dc9aca9cb6a7a'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Excelente profe, sin duda explica super claro y es un excelente guia en el curso, matricule con el sin miedo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'f66ca6ee7ee519979a4891550915f4ab558ee596978156b90077c36e78fad115'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El buen microfonito. Muy recomendado. Explica super claro los labs, las pruebas cortas conrresponden con la materia, La evaluacion es muy justa (Siga la rubrica). Meta con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '438bbf004f81a95698b6e1c1bdf5c321f50be0b2db8eaa0584dd127e82420af1'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'La verdad el profe es una teja tanto deprofesor como persona. Explica súper bien y no exige tanto en las evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '337beedbbdc269a9776f908ebad303f910e5261415bf8139d2aa42acc62b50ed'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El profe es excelente, cada clase explica el laboratorio que se va a hacer y la teoría de lo que se está viendo. Siempre esta dispuesto a ayudarlo a uno, tanto en clases como en horario de consulta. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-18T00:00:00+00:00'::TIMESTAMPTZ, '0dfd42fe194352a8a7c2311866a537cdab2648f9b6e6db5fffb41e31b13ceeef'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'La verdad el compa hace los labs bastante directos y fáciles de hacer. Siempre explica todo antes para que uno no se pierda, pero igual se le puede preguntar después y el mae le va responder. Las entregas las califica tuannis y le ayuda si no sabe hacer algo bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8664b9485ded45d4d92f20e4b74562d7031c0467ced2e7b6808aa3385b529389'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El profe puede parecer serio, pero es muy vacilón, lástima que no matriculé teoría con él, pero definitivamente volveré a llevar cursos con este profe. Se podría decir que es fácil, siempre y cuando uno cumpla con lo establecido, no saqué 100 por errores muy tontos de mi parte, pero es lograble.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '316e102443319df8b2929611b350afadcc051a5ca9946ad44f8432ca84aeb50f'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Por primera vez no lo recomiendo; si esta repitiendo de lo mejor; evaluaciones muy faciles y claro al evaluar; pero no da materia para estudiar en el examen de tipo seleccion unica; y hace ejercicios y se complica mucho'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-11-18T00:00:00+00:00'::TIMESTAMPTZ, '6440120bb55d4e2145beae6118c688a76efedff8da0f2eb7078e5f470ff5517d'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'El profe es bastante serio y califica lo que dice en la rubrica. La presentación del final del curso generalmente es virtual pero el la hizo presencial. Lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '50a15e2e13c8da0c3593f33a12f9a1578dc677a82bd159ce57367a14c5a69b41'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Muy buen profe, explica bastante bien todo, responde dudas, revisa justo y es muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '17c7e80dcffb17c9e49bf8a286cdefc03bde5e39ee4cbbedc204fd33816a2a7b'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'El profe explica bastante bien y brinda ayuda si uno la necesita. Lo importante es no faltar y conseguirse un buen grupo de trabajo (a veces cambia los grupos). Califica siempre lo que dice la rúbrica entonces es importante fijarse siempre y parece que es muy serio, pero es buena gente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '75c45c87ed88defbf0309d6f328377c3f29e5dbe9b6fefacfbf1b4714e29d390'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Explica muy bien, se ve gruñon pero no, la verdad es un personaje curioso, solo no falte se evita problemas y pues ya, el le explica cómo hacer los experimentos y los informes, entonces póngale bastante atención.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e1c1b8ad4588b7ef34caa06882ec88158ae711bf6c349af35717590c7ec22960'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El profe explica súper bien los experimentos, incluso el mismo los realiza por sí solo rápidamente para que quede más claro. La mayoría de los trabajos los califica el asistente, pero era bastante chill calificando. Súper fácil el curso con este profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'd3df1da9abe86a368d42c9a0c9840d939f6cb7b68a8575129fc9fa61babd5ae8'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Muy buen profe, explica bien y da buen feedback'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, '089b90cb3f988cc4ebd238b20431cce17aa4257ba25f3eba352f62df16676f80'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El profe es buena nota, sabe mucho, siempre fue super puntual con la clase y las evaluaciones. Suele calificar duro pero, califica respecto a la rúbrica que brinda con antelación. Dele sin miedo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '0973f54bd6af08c074982cb270e9a91b18ab2b67c52b46a3a29aeb7e6bbf1626'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'El profesor atiende consultas si se le pregunta. Evalúa de manera estricta. Conviene atender a algunas preferencias que menciona en clase. Dió lo mínimo necesario. Es un profesor justo que no incide positiva o negativamente en el resultado del curso, si se siguen los documentos de la cátedra.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'efee198f6cd62031809ba7d6903e8b60e81c3355c6ec6dd168f07843808d0bd5'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Califica de manera justa y es muy claro a la hora de dar retroalimentación. Parece enojón, pero es por la forma de hablar, así que si tiene dudas pregunte porque las aclara sin problema. Completamente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1515e561315a4bcd2d43635fe81144ea233623c468f39f432497737b7646e63b'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Parece que se enoja pero el maestro es una teja. La verdad califica super bien, si esta de opción tómelo de fijo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd80fb2b8d01875f3d3d1c414ef3b174d32e771ac0ab78941635e2116ba00602d'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Califica super suave, es concho a veces pero en realidad es una teja, si algo sale mal le ayuda a uno, se nota que lo quiere matar, pero no lo perjudica a uno. Explica muy bien y se nota que le apasiona el tema, logra que a uno tambien le interese algo como la incertidumbre'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8555905c081b5fd7fcffd60efed8801be5461b9deffa393bdf3ce927b3e558dc'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Buen profe, califica lo justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '69303d7c7241ca72bc85851e70044d2f98b253681c11d4a4d13c2be27b421a32'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es buen profe, aveces parece que se enoja por como habla jajaj pero es buena nota, se pasa bastante fácil'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'cc42767ed328c229920367dab8e3a72d3627a7044c12d80a95833d6a6a5343a8'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (211::BIGINT, 'Carlos da la sección de Simulación, las asignaciones son simples, aunque es complicado familiarizarse con COMSOL, él ayuda si se habla con tiempo y durante la clase resuelve cualquier pregunta (del curso o no), es hiper chistoso. El proyecto es casi solo simulación, recomendado empezarlo con tiempo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '4b26c4e810be231e83881b532ecf767f15a0bc16e40e0e63c9e870d7ca73dd7b'::TEXT, ARRAY[4147]::BIGINT[]),
    (211::BIGINT, 'Un pvto amo, es un crack, explica demasiado bien, es súper atento siempre apoya, presencial es demasiado bueno, la verdad califica regular pero sus explicaciones son tan excelentes que se ve que califica suave, con solo ir a clase pasa ya que el Mae hace la mayoría en clase, ???? % recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '910442815d4d92b850295ae39a1b28aa0fe697cac4956812668c1c8bc7b7dd0e'::TEXT, ARRAY[607]::BIGINT[]),
    (211::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-04-07T00:00:00+00:00'::TIMESTAMPTZ, '7e06b69a9570d0a6237a03c2ab3c983082c25873a32e5edb9cfe036ee58d52d7'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es un excelente profesor, explica muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '0190e9e035f4819f003020ea9ddeb749f5f89095a4258436d4f2df8affac98b2'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'A veces da la materia muy rápido y le estresa si la compu no le carga en 0,1 s, pero en general es muy bueno, se preocupa por los estudiantes, está dispuesto a ayudar, se le entiende bastante y el curso resulta muy útil, algunas tareas son complicadas pero puede dar tiempo extra y explicar más'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '77ab850a09a18cb264696e4f1e86c7b8a770c03b678d38284d1ed57b211ae1f6'::TEXT, ARRAY[4147]::BIGINT[]),
    (211::BIGINT, 'Explica hasta más de la cuenta y súper bien, va haciendo el inicio de las evaluaciones semanales en clase, califica suave y ayuda mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e0e6f16454bcebb9a4dd5692913153ac67e30b7e9156dd7ff9736e2b83808d51'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Un profesor excelente, explica muy claro (lo cual es muy poco común en física II), ayuda cuando hay dudas y no es muy estricto con sus trabajos, si tiene chance matricule con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '0cb9014380a6e5d53b6352e6993c65fea147825c8bbfcd78407aebb61be3a06e'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'El mejor profe que he tenido de la escuela de fisica, matriculen con el mae de una'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'f7f8261f1f16b9dba77ec363aa6a76b840e358c8ccf8c3c74e36d117ca666afe'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Buen profe, lo recomiendo, si puede llevarlo con él, hágalo, explica muy bien en clase y despeja dudas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'd2427f6e8b669f4a35cd72453045dbae42e144f7f2cfe3da9a3b5bf9c89d1b6e'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Deja todo MUY claro, lo guía a uno a través de los cálculos y responde cualquier duda que uno tenga. De los pocos profes que en laboratorio se preocupa porque uno entienda la materia y no solo haga informes. Sus clases son muy fluidas, se nota que las prepara bien. No dude en matricular con él!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7867be74f1090982e2645c87bfd359557605dce90c418ff4fb25f10bf0783997'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Da una buena explicación de como hacer los reportes de laboratorio así como los informes, genera buena retroalimentación con los errores cometidos y se preocupa porque todo que bastante claro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c09bca4ea4cd94cc10364bd1fdce732c0fe7592af05a6dbdfcee975d2a3db069'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'El profe explica paso por paso como realizar los cálculos y los informes, por lo que el curso se vuelve super fácil de pasar, además de tener presentaciones super cortas con la información que necesita.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dd70413d75899042ac99886c6ef555a95e80f897a3e2e66f9377f9b96cf0eaad'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Muy recomendado, da una muy buena guía para la elaboración de informes y demás entregas. Es de los profesores que no hace un laboratorio difícil y con su explicación durante la clase basta para las entregas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a7836bfb682056523674f028df09d4c5b3bbd25101bb6ab10d2c32bb24892b5c'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Las clases se entienden super bien, califica justo y es accesible a consulta. Si puede matricular con él, no lo dude.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5528088660ca1c736f569fc689c043539bc120618064685f8308ec66b9d76568'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Este profe sin duda es de los mejores profesores del TEC, explica perfecto, se le entiende todo, califica muy justo, ayuda mucho y siempre esta pendiente de las calificaciones. Este profe sabe demasiado de todo, si lo tiene como opción, seguramente sea la mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '016c2b4b95c2628fcedffbc53139118252b0f66264cdab99a6288a08c34b44bc'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Uno de los mejores profes de la escuela de física , las clases son por medio de teams y simpre trataba de que la materia quedara clara . Las tareas y trabajos las califica justo . Siempre que tenia consultas fuera del horario de clases por correo o por teams contestaba . Muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '8ca727bbec10898250b87cab0d88c8c17b601a2e6621e1c617b16c41cf9b4981'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, segundo curso que llevo con él. Explica muy claro la materia y si uno tiene una duda en clase él siempre trata de responderla. Hace bastantes ejemplos en clase y explica paso a paso todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '9a10c1a39e4b93e193f856c541fb3c77aeae26a13755d9c15c357b8665d92993'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'El profe explica súper bien toda la teoría y luego hace ejemplos, va paso a paso lo que ayuda un montón. Sus clases son muy largas, pero con solo verlas pasa súper bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '1f82af503e5cc2fcf412f21853fd27508fe94add9992aae7e664f5b1ee3aa3e5'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Es bastante bueno explicando y se nota que trata de dar la clase de la mejor manera, incluso virtualmente. Califica un poco duro pero si se le pone sí se pasa bien y hasta con buena nota. Atiende tarde correos pero es más rápido con consultas en Teams.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '5d31c82c83ada986b51daa723559cdf3a1d432c3e42f6128089cf6b7ea73d6b0'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'El profe se preocupó bastante durante la modalidad virtual, todas las semanas había que hacer un mínimo un reporte o un informe pero siempre siempre hacía una sesión donde explicaba el experimento que se hubiese hecho presencial.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '023115f4959e364c97f901e62c355debb29ba6be6ddd58af977b6f6c49dc2452'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Tiene un tono de voz muy muy fuerte pero no se asuste, así es él, parece que grita pero no es con intención.En general es un excelente profesor, volvería a llevar cualquier física con él y sé que aprendería y disfrutaría la clase. No es fácil, sí le va a exigir pero va a aprender es lo importante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'fc8e9ba4fa0da2a0973ffb8921c5e76bd7e9127227ee6800d663a6ad46a24051'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Se molesta si los estudiantes lleguen tarde. Explica muy claro. Deja muchos trabajos y los califica un toque duro, pero al fin y al cabo si te interesás un poco en el curso, pasás con buena nota. Es un excelente profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'e01a58e9ddf20712281d8e71008a799ecf0ca50f5cace3844493b509a4c2ca75'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es un dios. Super buena vibra, tiene tono de voz fuerte entonces parece que esta bravo jaja, pero el compa es toda una vibra. Full recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'b20c7f315d9973b1b8c87a42b69feb9e360ffecb4abcf16f3dd6790895088379'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Hace repasos rapidos de la teoria, la mayoria de sus clases presenciales las usa para hacer muchos ejercicios del libro y de examenes pasados. Ayuda bastante con los quices, y deja una tarea y un cuestionario en el tec digital por semana.Para ser semivirtual no demanda mas tiempo del necesario'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0a9f872a09a8616ba256957f078b5b727ce5b5b2b41bf48ad26353c1066aca4d'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, sin duda llevaría el curso de nuevo con él. La modalidad semi-virtual la supo aplicar y cualquier duda él atendía con mucho gusto. A veces se hacía despiches con las respuestas de algunas tareas, pero usted podía consultar con él la duda. Es vacilón y se preocupa por atender duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'ced16ea392fe05d87062e115294c6ab5224971817f04282319d16a34ac6b8389'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, '(Modalidad Semivirtual) Deja tareas y cuestionarios que sirven para estudiar usualmente se enreda a la hora de hacer los ejemplos, se enfoca en repetir lo que normalmente uno se equivocaría para que se evite. La asistencia no es obligatoria'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2018-12-04T00:00:00+00:00'::TIMESTAMPTZ, '36fc935bb1194f73658a4c995685f92aa3b9b4516ecdd0bba1bbdd06b8d45d7d'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Lo llevé Semi-Virtual, pero es sumamente pasable, deja varias tareas, pero sirven demasiado para el examen. Habla demasiado fuerte, pero es super cosi. Explica muy claro, pero revise todos los cálculos porque a veces se enrreda. De fijo llevaría todas las físicas con él'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '665bb49e4bcb2f7b82407831a65b4d0a29c3743cbbd28946ba08b9890bd0f690'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Se preocupa bastante porque uno siga el formato que él dice en los informes, y los califica duro. Fuera de eso es muy buen profe, ayuda mucho en clase y hasta le da puntos extra.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'd8236ad32e4196004e8600e0cd499ce5982acd6bb5f94cc485fc1a16f3d60bb2'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Para ser lab de física es muy exagerado para calificar los informes, observa cada detalle. Explica demasiado bien todo, lo recomiendo si quiere que lab de física se torne un curso de 3 créditos. TUANIS.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '03d68e118cf92f4fe6f4026b94ef4966cb714934743ce7959197842c15fc91dd'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Deja un folleto con problemas resueltos que sirven excelente como guía, consigalos aunque no lleve física con él y le va a ayudar muchísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-03-06T00:00:00+00:00'::TIMESTAMPTZ, '7b89a14b3333b5ae3242d84db07773d8142c1d9ca6f928e47dc9f76e538b4d2d'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Explica super claro la materia, resuelve ejercicios en clase y atiende las dudas, ademas facilita material para practicar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '4760a8a7c9b0dd9a0be538138198f0b844c293b65d7247fab7d274143181129c'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Demasiado buen profe, todos los profes deberian ser como él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '7ac306fd4a84e8f4ad69be8eeeff4854830c448f796a6625f796c0c01871226e'::TEXT, ARRAY[3021]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, no dude en matricular con él. A mi parecer de lo mejor de la escuela física, da la materia clara y hace ejercicios de exámenes viejos por lo cual llega bien preparado al examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '687aed0725b376f9b99c938f62870d3357c1d0405e448b6b8e55e3ebd5cd3af2'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'La verdad si quiere meter con él, hágalo sin miedo, es super claro y si usted no entiende le vuelve a explicar, no lo mata a uno en los examenes, deja muy buenas tareas (traen respuesta asegurandole un 100) pero si usted las hace, así viene el examen, va uno preparado para pasar bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '71a67b4ebbfd44dc39bfc923f53f0d2f0827d6c58ed76c1be3f2b0dcf6b1e53a'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-09-21T00:00:00+00:00'::TIMESTAMPTZ, '00b22398d54f2b14a58924241ee9d12ae4e85ab5a654b0764a57515e2d5a34e7'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Explica muy bien, se interesa por los estudiantes, por lo general deja tarea y quiz la semana antes del examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '18a1450f5c8050c861ca03459f396190b5df61b7757e119fdbea85c90f1945ed'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Buen profe, se le entiende bien cuando explica pero califica muy duro los informes de lab. No se preocupa por decirle a uno qué hizo mal... así que se cometen los mismo errores de nuevo y se pierden puntos con tonteras.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '06456a3aa19de486f9d002345174559482b50b630d56ed58cd2c7b8b6f8cc876'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es un excelente profe! Es muy ordenado con la materia y las clases, deja en claro los contenidos de las evaluaciones, explica muy bien las prácticas. Súper recomendado!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '25c05cd559b4921761fcc5550c607294c425130ea026255df55bcb68622bddbe'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es muy bueno, se le entiende todo. hace la clase entretenida. califica un poco duro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '8e4dfafe3861117e61942826299a9876e5b11f3e195bc5cc41b428539eb8af70'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Muy bueno la materia y los procedimientos siempre están claros ... No deja tantos informes y califica justo los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e67f141a128194608776e62c7ebe9768d353ca71ed5f4c3d3f3db965f934088a'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, divertido. Explica muy bien y hace muchos ejercicios.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '429e2baef3a1b9dec79234865173ab1502198347bc0b173eae37a424e26396bf'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Recomendado. Califica normal'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef7d1f3c772e28565538933e39625b773b68a13594277b8e362675c024a0e196'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'No es tan mal profe. Hay mejores pero él explica bien. Se enreda mucho, califica muy duro y no regala puntos para que lo tomen en cuenta pero para Física 3 al menos es pasable con él.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3e13753ddf58620504ab3494a97fd39fc4d189902cb2dcb409a4d3184ebf5384'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Es súper buen prof, es muy ordenado muy claro en las instrucciones. Su manera de ser es seria pero en realidad es bastante buena nota, muy amable y en el examen final trata de ver que realmente aprendimos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'a5c1936de477e5564e3c1d88e3a804e92627b2a2c8f6a9b045ce7f0227aabfb2'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Muy buen profesor! Explica excelente y hace bastantes ejercicios, recomendado en todos los sentidos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'cfaf7f51f09a1b31d2367804faaac043400cc6a606cc6c0ce88c32c4a0ad2e70'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Las clases se vuelven aburridas pero él es divertido. Trata de explicar la materia lo más que puede pero a veeeeces se enreda un poco. Tareas y quices en parejas y califica normal. El curso no es complicado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '97fdc573fccd36a02982edd106ea5a8b969790de9c11ce659a23bbeace697d10'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Buen profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-08-17T00:00:00+00:00'::TIMESTAMPTZ, '5f6fb3cb0ea63a4cec01c69fa585e362df77a4f99573ad0fc342c46e4216328d'::TEXT, ARRAY[3021]::BIGINT[]),
    (211::BIGINT, 'explica demasiado bien en clase y hace muchos ejercicios. En ocaciones los quices y las tareas son grupales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8da405a272c40f436e46a21248a8d9025ac2f8711683c7e7efd7fe41c0b18f30'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Sin duda el mejor para cualquier laboratorio de Fisica II, la clase no es tediosa ya que el hace chistes a cada rato, explica para que uno aprenda bien las cosas y le gustan los trabajos bien hechos a como el lo explica en clase, aunque aveces da miedo ir a preguntarle algo el es buena persona.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5c15aa971e7d24c6b31e00b402c439bbccd95545f07c0cca60d61628e2338b66'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Muy bueno en el lab explica todo antes de empezar. Sólo que si hay bastantes tareas y trabajos para un curso de un crédito.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '95610272c189ac0a7d7511ea19b1d54d47f14d5897873a5ba27c6c994843dfe7'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'El mejor profe de física que he tenido. En lab. explica todo el experimento antes de empezar, explica hasta el cuestionario previo, en caso de si uno llegó detrás del palo, se salva. Califica bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '351d922d57da8ae67e7e5c68efff0a97385622118ae551e06e288fd43cfba1cc'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es muy bueno explicando.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '70f3bc3620b04007666752876a3abc5f8e6310948dcadd152f89016dcf3a8791'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Para física 1 es el mejor pero para física 3 sinceramente se enreda mucho y no explica tan bien. Hay mejores para física 3 en serio'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f1d91d95c29b0ed060bc6a846bc964d5eb38d469e238b5fddc44fb375ec88e83'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Es un profesor gracioso, pero se empena en dar ejemplos que ayuden a comprender la teoria'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fc387d27aecd8ccd6b7e5175afc9ea16abf669f69999219b35eca1962df9fec0'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'El mejor profe de física!! Muy divertido y pura vida, le interesa que ud entienda, deja tareas largas pero con mucho tiempo, las tareas y quices es un grupos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2ae962ae5c50216ed06007b566432fc59faea03e5177e656dc56a1c89253bca3'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Muy bueno, pide todas las tareas colegiadas antes de cada examen y hace un quiz antes también..'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b4066837d041a0509823fb5f607a3afba0ce552b6551cf814911c6b8485dfbac'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Lo mejor de la escuela de Física! Recomendado !!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e06a4b1b4364ecd05623a7d1c58e381fd2535c35c8022b0ae5b549539b2c30d1'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Califica duro los informes y las evaluaciones en general, pero es súper bueno explicando. Calidad de profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '28ea61c7f7834e3200b0bf2761b0da91a7f7a7e4e295afe1d13dbb2657ff2922'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Explica super bien, califica bastante bien, le interesa que uno aprenda un profesor demasiado bueno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6da252a9af5b1fb33cd31f8449e35b6426cd57d5c7280bf5cbe9921313a5d4e4'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, explica demasiado bien, no califica duro y las tareas, aunque son largas, ayudan demasiado para el examen. Quices en pareja y cuaderno abierto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ffffed13091561c11e8fc69a7978a32d708fd6b9f136252f7fe7da1f503a73a6'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'El mejor profesor! Explica como ningún otro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'ce612ee84c1f245bf72933f1ac1e71ec85e195e09b9bebb7939bffc9b11e2c78'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Exelencte profesor, le importa que los estudiantes aprendan'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2016-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd7aedb55d9da30f31e7a783abb00814ec3f6876ac92df1bc8c68a8176361686f'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Buen profesor, las clases son entretenidas, las tareas ayudan mucho para los exámenes. Exc en consulta, califica suave.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'cc273e984bc6a6f5cba4a682b10cf72525c1aa7bedbf1e78c15e4833f0d8be1f'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Excelente profesor, no le teman, el le gusta el estudiante interesado en pasar, su metodología es buena, explica bien y sus tareas ayudan demasiado, es buena persona, pero mejor aun excelente profesor y con mucha vocación además de decir que es gracioso y nada aburrido.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ec00d9cff8205ab25aa2584d3ce14532a03d15e950e2374015688d01d7d22e95'::TEXT, ARRAY[922]::BIGINT[]),
    (211::BIGINT, 'Es muy buen profesor, la materia la da con la mejor claridad. Si usted hace las tareas, probablemente le va ir muy bien en los exámenes. Califica normal y es muy gracioso xD! Usa mucho los "chayotes" para dar ejemplos xD!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '4abe8e1f04daa494197af44566e28fdda70a756fdd77019f1aa3c54def3d94c6'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'El curso es muy duro, pero él deja tareas y es una salvada, si no entiende las tareas(son muy duras, igual que un examen) vaya a consulta, él casi que se las resuelve. Y explica muy bien :)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'fbb2cab34f9b159def57f1ecb4c6a28ae02286e3dab2d18e92b2cd3ba90e4c33'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Deja mucha tarea, califica tuanis. Es un crack'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'abb7d4314c99fe64594f14e82a3421c3132347224656ec1b78378dc39289c09e'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Excelente profe, pone tareas para cada examen que ayudan mucho para estudiar, explica muy bien y es super pura vida, las clase es de las mejores que he tenido'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6aefd7d77db536acd84f778a64c6e9dbfef89fc02260b5126352955a38315384'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Muy bueno para laboratorio! sí lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '28f0eaaf3657b964153a3325a0d4133869542d62f7f61876d62aba1ce78f7ada'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'excelente profe, pone tareas de cada tema a nivel de examen, no le rinde la clase para hacer muchos ejercicios pero los que hace los explica super bien en la pizarra escribe cada paso y porque lo hizo. Frase: QUE TUANIS!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'b744dcb77f9f0599467cfdad1fb07a7439e82cc8b85632361ab2b28568aa7f1d'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Es muy buen profe, explica uno o dos problemas por clase, pero muy bien explicados y las tareas son a nivel de examen, entonces uno va a estudiando desde semana 2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5b3190f53d42c24742ea6bca3b212cab126a37a2f7cb8b76b02d43fd2212bf3e'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Excelente para fisica 2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'b2cfe0dc0f9a807bda80d06643b7aa0a3989b2d1f19405cdd9f88fd2fb17ed7c'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Explica muy bien pero demasiado, más bien se aburre uno que le expliquen hasta como sumar. Si se quiere dormir matricule. Usa presentaciones en clase'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '3c0c127dbbdc7b9dbc39eb90f7e7e6417583fa8b993df8c04ed48ed2206a88e8'::TEXT, ARRAY[631]::BIGINT[]),
    (211::BIGINT, 'Bastante bueno, explica muy bien los ejemplos y ayuda con las tareas. 100% recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '4e6b47b39b4dd2fdfbee32ac351044a7823b8add2e75b249456ea4aeb82de3f7'::TEXT, ARRAY[604]::BIGINT[]),
    (211::BIGINT, 'Explica muy bien la teoría, porque sus presentaciones ayudan bastante, y los ejemplos los explica paso a paso entonces a la hora de estudiar sirve bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'b1490aae661b57017af8c9c71278786cdf1374e461971c46d9222377f40449e6'::TEXT, ARRAY[604]::BIGINT[]),
