    (211::BIGINT, 'Explica muy bien. Maneja un sarcasmo que hace la clase entretenida. Califica suave. Y a mí el promedio me daba 77,2 y me lo redondeó a 80 :D'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b8cf6ad64c462ddfe7a6608dc8090b5a1533cd7018b64564abde75a829963b93'::TEXT, ARRAY[604]::BIGINT[]),
